
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_g96_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_g96", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.343184140932370e+00, -4.260672624223790e+00, -4.145105820818581e+00, -3.985128314297145e+00, -3.767380407072884e+00, -3.478106650295302e+00, -3.106968392052727e+00, -2.653985037600347e+00, -2.139126484972018e+00, -1.607386982223462e+00, -1.097929209769268e+00, -7.141027771872945e-01, -6.073959797059388e-01, -5.050854121587586e-01, -3.712175764124173e-01, -2.487729341835871e-01, -1.753391521240279e-01, -1.765338650044595e-01, -3.072129375637076e-01, -8.573618068942885e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


